const PLACES=window.DESTINATIONS || FALLBACK_PLACES;
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>{const paths={plus:'M12 5v14M5 12h14',minus:'M5 12h14',check:'m5 12 4 4 10-10',up:'m6 15 6-6 6 6',down:'m6 9 6 6 6-6',close:'m6 6 12 12M18 6 6 18'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]}"/></svg>`};
const demoRoute=()=>[{id:'tokyo',nights:4},{id:'kanazawa',nights:3},{id:'takayama',nights:2},{id:'kyoto',nights:5}];
let state={start:'2026-11-01',end:'2026-11-15',stops:demoRoute(),dayItems:[],accommodations:[],arrivalPlaceId:null,departurePlaceId:null};
let detailReturn=null,mapZoom=1,mapCenter=[360,330],pan=null;
let editGeneration=0,routingGeneration=0;
let history=[],filter='all',search='',geometry=null,toastTimer;
const STORAGE_KEY='tabi-japan-prototype-v1';
try{const saved=window.TripServices?null:JSON.parse(localStorage.getItem(STORAGE_KEY));if(saved&&validDate(saved.start)&&validDate(saved.end)&&dateValue(saved.end)>dateValue(saved.start)&&Array.isArray(saved.stops)&&saved.stops.every(s=>PLACES.some(p=>p.id===s.id)&&Number.isInteger(s.nights)&&s.nights>0&&s.nights<=30)&&new Set(saved.stops.map(s=>s.id)).size===saved.stops.length)state=saved;}catch{}
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s+'T00:00:00Z'))&&new Date(Date.parse(s+'T00:00:00Z')).toISOString().slice(0,10)===s;}
state.dayItems=Array.isArray(state.dayItems)?state.dayItems.filter(validDayItem):[];
state.accommodations=Array.isArray(state.accommodations)?state.accommodations:[];
let planningStage="route";
function validDayItem(item){return item&&typeof item.uid==='string'&&validDate(item.date)&&PLACES.some(p=>p.id===item.destinationId)&&['activity','daytrip','free'].includes(item.type)&&typeof item.title==='string'&&item.title.length<=250;}
function dateValue(s){return Date.parse(s+'T00:00:00Z');}
function addDays(s,n){return new Date(dateValue(s)+n*86400000).toISOString().slice(0,10);}
function dateLabel(s,year=false){return new Intl.DateTimeFormat('de-DE',{day:'numeric',month:'short',...(year?{year:'numeric'}:{}),timeZone:'UTC'}).format(new Date(dateValue(s)));}
function tripNights(){return Math.round((dateValue(state.end)-dateValue(state.start))/86400000);}
function assigned(){return state.stops.reduce((a,s)=>a+s.nights,0);}
function place(id){return PLACES.find(p=>p.id===id);}
function photo(p){const image=window.CATALOGUE_PHOTOS?.[p.photo]||window.PHOTOS?.[p.photo];return image?.license?image:null;}
function commit(change){cancelRouteDrag();editGeneration++;history.push(JSON.stringify(state));if(history.length>30)history.shift();change();save();render();}
function save(){if(window.TripServices){window.TripServices.save(JSON.parse(JSON.stringify(state)));return;}try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));$('#saveStatus').textContent='Entwurf auf diesem Gerät gespeichert · keine Cloud-Synchronisierung';}catch{$('#saveStatus').textContent='Speichern nicht möglich · Entwurf bleibt in dieser geöffneten Ansicht';}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function addPlace(id){if(state.stops.some(s=>s.id===id)){toast('Dieser Ort ist bereits in deiner Route.');return;}commit(()=>state.stops.push({id,nights:place(id).nights}));toast(`${place(id).name} zu deiner Route hinzugefügt`);}
function visiblePlaces(){const results=PLACES.filter(p=>(filter==='all'||p.tags.includes(filter))&&`${p.name} ${p.region} ${p.short} ${p.activities.join(' ')}`.toLocaleLowerCase('de').includes(search));const interests=state.interests||[];return interests.length?results.sort((a,b)=>b.tags.filter(tag=>interests.includes(tag)).length-a.tags.filter(tag=>interests.includes(tag)).length):results;}
function renderPlaces(){const list=visiblePlaces();$('#resultCount').textContent=`${list.length} Orte`;$('#places').innerHTML=list.length?list.map(p=>{const added=state.stops.some(s=>s.id===p.id),im=photo(p);return `<article class="place-row">${im?`<img class="place-photo" src="${esc(im.url)}" alt="${esc(p.name)}" loading="lazy" referrerpolicy="no-referrer">`:`<div class="place-photo" aria-hidden="true"></div>`}<button class="place-body" data-detail="${p.id}"><h3>${p.name}</h3><p>${p.short}</p><span class="place-detail-hint">Ort ansehen <span aria-hidden="true">↗</span></span><div class="place-tags">${p.nights} Nächte als Ausgangspunkt${p.tags.includes('quiet')?' · Entdeckung':''}</div></button><button class="place-add ${added?'added':''}" data-add="${p.id}" aria-label="${added?p.name+' ist in der Route':p.name+' hinzufügen'}" aria-pressed="${added}">${icon(added?'check':'plus')}</button></article>`}).join(''):'<div class="empty"><h3>Noch kein Treffer.</h3><p>Versuche einen anderen Ortsnamen oder wähle einen anderen Filter.</p><button class="button outline" id="resetSearch">Suche zurücksetzen</button></div>';}
function transfer(a,b,date=state.start){if(window.TransferEngine)return window.TransferEngine.lookup(a,b,date);const pairs={'tokyo|kanazawa':['Bahn',180],'kanazawa|takayama':['Bahn / Bus',150],'takayama|kyoto':['Bahn',240],'kyoto|kinosaki':['Bahn',165],'kyoto|naoshima':['Bahn + Fähre',240],'tokyo|kamakura':['Bahn',75],'tokyo|nikko':['Bahn',150],'naoshima|iya':['Bahn / Straße',210]};const key=[a.id,b.id].join('|'),reverse=[b.id,a.id].join('|');if(pairs[key]||pairs[reverse]){const [mode,min]=pairs[key]||pairs[reverse];return{mode,min,known:true,label:'Illustrative Transferdauer · kein Fahrplan'};}const distance=haversine(a,b);return{mode:(a.id==='yakushima'||b.id==='yakushima')?'Inselanreise prüfen':(a.id==='naoshima'||b.id==='naoshima')?'Bahn + Fähre prüfen':'Verbindung prüfen',min:null,known:false,label:`${Math.round(distance)} km Luftlinie · Dauer offen`};}
function haversine(a,b){const r=x=>x*Math.PI/180;const x=Math.sin(r(b.lat-a.lat)/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(r(b.lon-a.lon)/2)**2;return 6371*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}
function duration(n){if(n==null)return'Dauer offen';if(n===0)return'0 Min.';const h=Math.floor(n/60),m=n%60;return `${h?h+' Std.':''}${h&&m?' ':''}${m?m+' Min.':''}`;}
function itinerary(){let day=state.start;return state.stops.map(s=>{const p=place(s.id),arrival=day;day=addDays(day,s.nights);return{...s,p,arrival,departure:day};});}
function renderRoute(){routingGeneration++;const rows=itinerary(),minutes=rows.slice(0,-1).map((r,i)=>transfer(r.p,rows[i+1].p,r.departure).min),total=minutes.reduce((a,n)=>a+(n||0),0),unknown=minutes.some(n=>n==null);$('#routeDates').textContent=`${dateLabel(state.start)} – ${dateLabel(state.end,true)}`;$('#routeTotals').innerHTML=`<div><strong>${state.stops.length}</strong><span>Orte</span></div><div><strong>${assigned()}</strong><span>von ${tripNights()} Nächten</span></div><div><strong>${total?duration(total):'—'}</strong><span>Transferorientierung${unknown?' + offene':''}</span></div>`;$('#routeList').innerHTML=rows.length?rows.map((r,i)=>`<article class="stop" data-stop="${r.id}"><div class="stop-leading"><span class="stop-number">${i+1}</span><button class="drag-handle" data-drag="${r.id}" aria-label="${r.p.name} ziehen, um die Etappe zu verschieben" aria-describedby="dragHelp"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5h1m6 0h1M8 12h1m6 0h1M8 19h1m6 0h1"/></svg></button></div><div class="stop-body"><div class="stop-title"><button class="place-link" data-detail="${r.id}">${r.p.name}</button><button class="remove-control" data-remove="${r.id}" aria-label="${r.p.name} aus Route entfernen">${icon('close')}</button></div><p class="stop-days">${dateLabel(r.arrival)} – ${dateLabel(r.departure)}</p><div class="stop-controls"><div class="night-control"><button class="small-control" data-night="${r.id}" data-delta="-1" aria-label="Eine Nacht weniger in ${r.p.name}" ${r.nights<=1?'disabled':''}>${icon('minus')}</button><span>${r.nights} ${r.nights===1?'Nacht':'Nächte'}</span><button class="small-control" data-night="${r.id}" data-delta="1" aria-label="Eine Nacht mehr in ${r.p.name}" ${r.nights>=30?'disabled':''}>${icon('plus')}</button></div><div class="order-controls"><button class="small-control" data-move="${r.id}" data-delta="-1" aria-label="${r.p.name} nach vorne verschieben" ${i===0?'disabled':''}>${icon('up')}</button><button class="small-control" data-move="${r.id}" data-delta="1" aria-label="${r.p.name} nach hinten verschieben" ${i===rows.length-1?'disabled':''}>${icon('down')}</button></div></div></div></article>${i<rows.length-1?(()=>{const t=transfer(r.p,rows[i+1].p,r.departure);return `<div class="transfer"><strong>${t.mode} · ${duration(t.min)}</strong><span>${esc(t.label)}</span>${t.source?`<a href="${esc(t.source)}" target="_blank" rel="noopener">Betreiberinformationen ↗</a>`:t.planningUrl?`<a href="${esc(t.planningUrl)}" target="_blank" rel="noopener">Verbindung recherchieren ↗</a>`:''}${routingPanel(r,rows[i+1])}</div>`})():''}`).join(''):'<div class="empty"><h3>Deine Reise beginnt hier.</h3><p>Füge einen Ort aus der Liste oder über die Karte hinzu. Die Nächte und Etappen kannst du jederzeit ändern.</p></div>';const diff=tripNights()-assigned();$('#routeBalance').classList.toggle('warning',diff<0);$('#routeBalance').textContent=diff===0?'Alle Nächte verteilt. Deine Route passt in den Zeitraum.':diff>0?`${diff} ${diff===1?'Nacht ist':'Nächte sind'} noch frei. Lass Raum für einen weiteren Ort oder mehr Zeit vor Ort.`:`${-diff} ${diff===-1?'Nacht':'Nächte'} zu viel geplant. Kürze einen Aufenthalt oder verlängere den Zeitraum.`;$('#undoBtn').disabled=!history.length;$('#exportBtn').disabled=!rows.length&&!state.dayItems.length;$('#clearBtn').disabled=!rows.length&&!state.dayItems.length;renderDayItems();renderQualityHints();renderMap();}
const seasons={winter:{name:'Winter',subtitle:'Ruhe, Onsen und winterliche Landschaften',weather:'Kühl bis kalt',crowds:'Regional verschieden',event:'Winterkultur',text:'Ein Beispielprofil für Winterreisen: Städte und Onsen können gut passen. Bergregionen, Schnee und Winterverkehr benötigen eine gesonderte Prüfung.',caution:'Weniger Andrang ist keine landesweite Garantie. Feiertage und Wintersportorte können stark nachgefragt sein.',festival:'Winterbeleuchtung und regionale Schneeveranstaltungen sind Rechercheansätze. Es sind keine Jahresdaten bestätigt.'},spring:{name:'Frühling',subtitle:'Blütenzeit mit regional unterschiedlichen Zeitfenstern',weather:'Mild, wechselhaft',crowds:'Oft stärker',event:'Frühlingsfeste',text:'Ein Beispielprofil für den Frühling: Blüte und Temperaturen entwickeln sich regional unterschiedlich. Ein festes Blühdatum wird hier nicht vorhergesagt.',caution:'Blütenzeit und Feiertage können zu hohem Andrang führen. Ein kleinerer Ort ist nicht automatisch leer.',festival:'Frühlingsfeste und Blütenveranstaltungen müssen für das gewählte Jahr bei Veranstaltern geprüft werden.'},summer:{name:'Sommer',subtitle:'Festivals und Landschaften mit Wetterpuffern',weather:'Warm bis heiß',crowds:'An Events stärker',event:'Sommerfeste',text:'Ein Beispielprofil für den Sommer: Hitze, Feuchtigkeit und Regen können die Planung beeinflussen. Regionen und Höhenlagen unterscheiden sich deutlich.',caution:'Festivals, Feiertage und Ferien verändern den Andrang. Plane Ruhe und flexibel nutzbare Zeit ein.',festival:'Sommerfeste sind ein Rechercheansatz, zum Beispiel Nebuta in Aomori. Der Prototyp bestätigt keine Termine oder Durchführung.'},autumn:{name:'Herbst',subtitle:'Ein schöner Ausgangspunkt für eine Kulturreise',weather:'Oft mild, später kühl',crowds:'An Highlights stärker',event:'Herbstkultur',text:'Ein Beispielprofil für den Herbst: Kulturorte und Landschaften lassen sich gut verbinden. Die Blattfärbung hängt von Region, Höhenlage und tatsächlichem Wetter ab.',caution:'Beliebte Gärten und Aussichtspunkte können stark besucht sein. Saisonprofile sind keine Andrangmessung.',festival:'Herbstveranstaltungen sind regionale Rechercheansätze. Takayamas Herbstfest etwa gehört typischerweise in den Oktober; für deine konkreten Tage ist hier kein Festival bestätigt.'}};
function seasonOf(m){return m<=2||m===12?'winter':m<=5?'spring':m<=8?'summer':'autumn';}
function assessment(){const keys=[];for(let d=state.start;dateValue(d)<=dateValue(state.end);d=addDays(d,1)){const k=seasonOf(Number(d.slice(5,7)));if(!keys.includes(k))keys.push(k);}return{keys,profile:seasons[keys[0]]};}

function routeAssessment(){return window.SeasonEngine?.assess(state,PLACES);}
function renderSeason(){$('#seasonSummary').innerHTML=window.TripSeasonView.html(state,routeAssessment());}
function regionalClimateHtml(result,forecasts=false){return '<p class="intro">'+esc(result.forecastNotice)+' Normalperiode '+esc(result.normalPeriod)+'.</p>'+result.regional.map(r=>'<section class="assessment-block"><h3>'+esc(r.name)+' · '+dateLabel(r.arrival)+' – '+dateLabel(r.departure)+'</h3>'+(r.missing?'<p>'+r.notes.map(esc).join(' ')+'</p>':'<div class="climate-values"><span><strong>'+r.meanC+' °C</strong>Monatsmittel, zeitlich gewichtet</span><span><strong>'+r.minC+'–'+r.maxC+' °C</strong>Mittlere Monats-Tiefst-/Höchstwerte</span></div><p><strong>'+esc(r.suitability)+'</strong></p><p>'+r.months.map(m=>esc(m.month||'')+(m.month?' · ':'')+m.precipMm+' mm Niederschlag / Monat').join('; ')+' · historische Normalwerte</p><p><strong>Andrang '+esc(r.crowd.level)+':</strong> '+esc(r.crowd.reasons.join('; ')||'Keine besonderen saisonalen Verstärker erfasst.')+'</p><p>'+esc(r.crowd.method)+'</p>'+r.notes.map(n=>'<p>'+esc(n)+'</p>').join('')+'<p class="source-note"><a href="'+esc(r.source)+'" target="_blank" rel="noopener">JMA · '+esc(r.station)+' · '+esc(r.normalPeriod)+'</a></p>'+(forecasts?'<div class="forecast-block" data-forecast="'+esc(r.id)+'"><p>Kurzfristprognose wird geprüft …</p></div>':''))+'</section>').join('');}
function eventsHtml(result){return '<section class="assessment-block"><h3>Festivals und Veranstaltungen</h3>'+(result.events.length?result.events.map(event=>'<article class="festival-item"><strong>'+esc(event.name)+' · '+esc(event.place)+'</strong><p class="festival-status">'+(event.status==='confirmed'?'Jahrestermin bestätigt':'Saisonaler Hinweis · Jahrestermin offen')+'</p><p>'+esc(event.description)+' '+esc(event.period)+'.</p><p>'+esc(event.notice)+' '+(event.distanceKm!==null?event.distanceKm+' km Luftlinie zur nächsten Etappe.':'')+'</p><a href="'+esc(event.occurrence?.source||event.source)+'" target="_blank" rel="noopener">Quelle und Jahresprogramm prüfen ↗</a></article>').join(''):'<p>Für diese Route und diesen Zeitraum ist kein passender Festivalhinweis in der kuratierten Auswahl erfasst. Das belegt nicht, dass keine Veranstaltungen stattfinden.</p>')+'</section><section class="assessment-block"><h3>Feiertage im Reisezeitraum</h3>'+(result.holidays.length?'<ul>'+result.holidays.map(h=>'<li>'+dateLabel(h.date,true)+' · '+esc(h.label)+'</li>').join('')+'</ul>':'<p>Keine erfassten gesetzlichen Feiertage innerhalb der Reisedaten.</p>')+result.notes.map(n=>'<p>'+esc(n)+'</p>').join('')+(result.holidaySource?'<p><a href="'+esc(result.holidaySource)+'" target="_blank" rel="noopener">Offizieller Feiertagskalender ↗</a></p>':'')+'</section>';}
let seasonRequest=0;const forecastCache=new Map();
async function refreshForecasts(result){const request=++seasonRequest;await Promise.all(result.regional.filter(r=>!r.missing&&r.office).map(async r=>{const key=[r.office,r.arrival,r.departure].join('|');const cached=forecastCache.get(key);let data=cached&&Date.now()-cached.at<3600000?cached.data:null;try{if(!data&&window.TripServices?.forecast){data=await window.TripServices.forecast(r.office,r.arrival,addDays(r.departure,-1));if(['available','outside_horizon'].includes(data.status))forecastCache.set(key,{data,at:Date.now()});}}catch{data={status:'provider_unavailable'};}if(request!==seasonRequest||!$('#seasonDialog').open)return;const target=document.querySelector('[data-forecast="'+r.id+'"]');if(!target)return;if(data?.status==='available'){const categories={'1':'Sonniges Wetter','2':'Bewölktes Wetter','3':'Regen','4':'Schnee'};target.innerHTML='<h4>Regionale JMA-Prognose · '+esc(data.referenceArea||'Referenzgebiet')+'</h4><p>Ausgabe: '+esc(data.issuedAt||'offen')+'. '+esc(data.resolution)+'</p>'+data.days.map(d=>!d.weatherCode?'<p>'+dateLabel(d.date)+': Für dieses Datum liegt keine Prognose vor.</p>':'<p>'+dateLabel(d.date)+': '+esc(categories[String(d.weatherCode)[0]]||'Wetterlage')+' (JMA-Code '+esc(d.weatherCode)+')'+(d.precipitationProbability!==null?' · Regenwahrscheinlichkeit '+d.precipitationProbability+' %':'')+(d.confidence?' · JMA-Verlässlichkeit '+esc(d.confidence):'')+'</p>').join('')+'<p><a href="'+esc(data.source)+'" target="_blank" rel="noopener">JMA-Datenquelle ↗</a></p>'; }else target.innerHTML='<h4>Kurzfristprognose</h4><p>'+({outside_horizon:'Für diesen Aufenthalt liegt noch keine Kurzfristprognose vor. JMA deckt nur die nächsten Tage ab.',stale:'Die empfangene Prognose ist veraltet und wird deshalb nicht als aktuelles Wetter angezeigt.',provider_unavailable:'Wetterquelle gerade nicht erreichbar. Erneutes Öffnen der Einschätzung versucht den Abruf erneut.'}[data?.status]||'Livewetter ist in dieser Umgebung nicht verfügbar.')+'</p>'; }));}
function seasonDetails(){const result=routeAssessment();$('#seasonContent').innerHTML=result?'<h2>Reisezeit für deine Etappen</h2><p class="intro">'+dateLabel(state.start,true)+' – '+dateLabel(state.end,true)+'. '+esc(result.method)+'</p>'+regionalClimateHtml(result,true)+eventsHtml(result):'<h2>Saisonorientierung</h2><p>'+esc(assessment().profile.text)+'</p>';$('#seasonDialog').showModal();if(result)refreshForecasts(result);}

function details(id){const active=document.activeElement;detailReturn=active?.matches('[data-detail]')?{id,map:active.closest('#mapPins')!==null}:null;const p=place(id);$('#detailContent').innerHTML=window.DestinationView.html({place:p,photo:photo(p),insights:window.DESTINATION_INSIGHTS?.[id],geometry,added:state.stops.some(s=>s.id===id),formHtml:dayPlanForm(p)});$('#detailDialog').showModal();}
function overviewTable(){const rows=itinerary();return `<table class="overview-table"><thead><tr><th>Aufenthalt</th><th>Ort</th><th>Nächte</th><th>Weiterreise</th></tr></thead><tbody>${rows.map((r,i)=>{const t=i<rows.length-1?transfer(r.p,rows[i+1].p,r.departure):null;return `<tr><td>${dateLabel(r.arrival)}<br>– ${dateLabel(r.departure)}</td><td><strong>${r.p.name}</strong><span>${r.p.region}</span></td><td>${r.nights}</td><td>${t?`${esc(t.mode)}<span>${duration(t.min)} · ${esc(t.label)}</span>${t.source?`<a href="${esc(t.source)}" target="_blank" rel="noopener">Betreiberquelle</a>`:t.planningUrl?`<a href="${esc(t.planningUrl)}" target="_blank" rel="noopener">Verbindung prüfen</a>`:''}`:'Abreise / Anschluss offen'}</td></tr>`}).join('')}</tbody></table>`;}
function entryExitSummary(){return 'Ankunftsort: '+(place(state.arrivalPlaceId)?.name||'offen')+' · Abreiseort: '+(place(state.departurePlaceId)?.name||'offen');}
function overview(){const rows=itinerary();$('#overviewContent').innerHTML=`<h2>Deine Reise auf einen Blick</h2><p class="intro">${dateLabel(state.start,true)} – ${dateLabel(state.end,true)} · ${tripNights()} Nächte verfügbar · ${assigned()} Nächte geplant</p><p class="entry-exit-overview">${esc(entryExitSummary())}. Internationale Flugtage, konkrete Flughäfen und Hotelwege separat planen.</p>${rows.length?overviewTable(): '<p>Übernachtungsorte sind noch offen.</p>'}${dayItemsTable()}${accommodationSummary()}<div class="route-balance ${assigned()>tripNights()?'warning':''}">${esc($('#routeBalance').textContent)}</div><div class="overview-actions"><button class="button primary" id="overviewExport" ${rows.length||state.dayItems.length?'':'disabled'}>PDF herunterladen</button><button class="button outline" id="overviewPrint">Druckansicht</button><p>Eigenständiges PDF mit Karte, Tagesplan und Quellen.<br>Klimanormalwerte, offene Jahrestermine und Transferorientierungen bleiben gekennzeichnet.</p></div>`;$('#overviewDialog').showModal();}
function printPlan(print=true){const rows=itinerary();if(!rows.length&&!state.dayItems.length)return;$('#printContent').innerHTML=`<h1>Dein Weg durch Japan</h1><p>${dateLabel(state.start,true)} – ${dateLabel(state.end,true)} · ${assigned()} geplante Nächte</p><p>${esc(entryExitSummary())}. Flughafen- und Hoteltransfers sind noch offen.</p><p class="print-note">Prototyp · Planungsentwurf · Erstellt am ${new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Zurich'}).format(new Date())}. Klimanormalwerte sind keine Prognose. Festivaltermine folgen ihrem jeweiligen Quellenstatus. Transferzeiten sind Orientierung ohne Wartezeiten, keine bestätigten Verbindungen.</p><div class="print-route">${rows.map(r=>r.p.name).join(' → ')}</div>${overviewTable()}${dayItemsTable()}${accommodationSummary()}<p>${esc($('#routeBalance').textContent)}</p><h2>Reisezeit</h2>${routeAssessment()?regionalClimateHtml(routeAssessment())+eventsHtml(routeAssessment()):assessment().keys.map(k=>seasons[k].text).join(' ')}<div class="print-details"><h2>Deine Orte und Erlebnisse</h2>${rows.map(r=>`<div class="print-stop"><h3>${r.p.name} · ${r.nights} Nächte</h3><p>${r.p.desc}</p><p><strong>Besonders schön:</strong> ${r.p.pro}</p><p><strong>Beachten:</strong> ${r.p.con}</p><p>${r.p.activities.join(' · ')}</p><p class="print-note">Quelle zur weiteren Prüfung: <a href="${r.p.source}">${r.p.source}</a></p></div>`).join('')}</div>`;document.querySelectorAll('dialog[open]').forEach(d=>d.close());if(print)window.print();}

async function exportPlan(){if(pdfBusy||(!state.stops.length&&!state.dayItems.length))return;const frozen=JSON.parse(JSON.stringify(state)),rows=itinerary();const snapshot={state:frozen,stays:rows,activityData:JSON.parse(JSON.stringify(Object.fromEntries(Object.entries(window.ACTIVITY_DATA||{}).filter(([id])=>frozen.stops.some(stop=>stop.id===id)||frozen.dayItems.some(item=>item.destinationId===id))))),places:PLACES.filter(p=>frozen.stops.some(s=>s.id===p.id)||frozen.dayItems.some(item=>item.destinationId===p.id||item.baseId===p.id)||frozen.arrivalPlaceId===p.id||frozen.departurePlaceId===p.id||(frozen.accommodations||[]).some(a=>a.destinationId===p.id)),transfers:rows.slice(0,-1).map((r,i)=>transfer(r.p,rows[i+1].p,r.departure)),assessment:window.SeasonEngine?.assess(frozen,PLACES)||null,hotelData:JSON.parse(JSON.stringify(Object.fromEntries((frozen.accommodations||[]).map(a=>[a.destinationId,(window.JAPAN_HOTELS_BY_DESTINATION?.[a.destinationId]||[]).filter(h=>h.id===a.hotelId)])))),insightsData:JSON.parse(JSON.stringify(Object.fromEntries(Object.entries(window.DESTINATION_INSIGHTS||{}).filter(([id])=>frozen.stops.some(s=>s.id===id)||frozen.dayItems.some(i=>i.destinationId===id))))),geometry,createdAt:new Date().toISOString(),revision:cloudRevision,unsaved:!['ready','saved'].includes(cloudStatus),warnings:[...new Set([...frozen.dayItems.flatMap(dayItemWarnings),...qualityWarnings()])],createdDate:new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Zurich'}).format(new Date())};printPlan(false);pdfBusy=true;$('#exportBtn').disabled=true;$('#exportBtn').setAttribute('aria-busy','true');toast('Dein PDF wird erstellt …');try{const result=await window.TabiPDF.download(snapshot);toast('PDF heruntergeladen · '+result.pages+' Seiten'+(result.unicode?' · Originalnotizen im JSON-Anhang':''));}catch(error){toast('PDF konnte nicht erstellt werden. Über den Reiseüberblick ist die Druckansicht verfügbar.');console.error('PDF export failed',error);}finally{pdfBusy=false;$('#exportBtn').removeAttribute('aria-busy');$('#exportBtn').disabled=!state.stops.length&&!state.dayItems.length;}}

function project(lon,lat){return[(lon-122)*28+20,(46.1-lat)*28+20];}

let mapRenderFrame=null;
function scheduleMapRender(){if(mapRenderFrame!==null)return;mapRenderFrame=requestAnimationFrame(()=>{mapRenderFrame=null;renderMap();});}
function renderMap(){const svg=$('#japanMap');if(!geometry||!svg||svg.clientWidth<=0||svg.clientHeight<=0)return;const available=new Set(visiblePlaces().map(p=>p.id)),rows=itinerary(),scale=Math.min(svg.clientWidth/(720/mapZoom),svg.clientHeight/(660/mapZoom)),markers=new Map(),occupied=[];
 rows.forEach(r=>{const [x,y]=project(r.p.lon,r.p.lat);let marker=[x,y],step=0;while(occupied.some(other=>Math.hypot((marker[0]-other[0])*scale,(marker[1]-other[1])*scale)<28)&&step<20){step++;marker=[x+(step%2?1:-1)*Math.ceil(step/2)*8/scale,y+(step%2?1:-1)*Math.ceil(step/2)*20/scale];}occupied.push(marker);markers.set(r.id,marker);});
 $('#routeLines').innerHTML=rows.slice(0,-1).map((r,i)=>{const a=project(r.p.lon,r.p.lat),b=project(rows[i+1].p.lon,rows[i+1].p.lat);return '<path class="route-line" d="M'+a[0]+','+a[1]+' L'+b[0]+','+b[1]+'"/>';}).join('');const labelBoxes=[];
 function labelOffset(p,point){const width=p.name.length*6.6;const options=[[15,4,'start'],[-15,4,'end'],[14,-20,'start'],[-14,-20,'end'],[14,28,'start'],[-14,28,'end'],[15,46,'start'],[-15,-38,'end']];for(const option of options){const x=point[0]*scale+option[0]-(option[2]==='end'?width:0),y=point[1]*scale+option[1]-12,box={x,y,w:width,h:16};if(!labelBoxes.some(o=>box.x<o.x+o.w+5&&box.x+box.w+5>o.x&&box.y<o.y+o.h+5&&box.y+box.h+5>o.y)&&!occupied.some(o=>o!==point&&o[0]*scale>=x-8&&o[0]*scale<=x+width+8&&o[1]*scale>=y-8&&o[1]*scale<=y+24)){labelBoxes.push(box);return option;}}return null;}
 const ordered=[...PLACES.filter(p=>markers.has(p.id)),...PLACES.filter(p=>!markers.has(p.id))];const contents=ordered.map(p=>{const index=rows.findIndex(r=>r.id===p.id),selected=index>=0,actual=project(p.lon,p.lat),point=markers.get(p.id)||actual;const specific=search||filter!=='all';if(!selected&&mapZoom===1&&!specific&&PLACES.length>15&&PLACES.indexOf(p)%8!==0)return '';if(!selected&&occupied.some(o=>Math.hypot((point[0]-o[0])*scale,(point[1]-o[1])*scale)<32))return '';const showLabel=selected||available.has(p.id)&&(PLACES.length<=15||mapZoom>=3||specific),offset=showLabel?labelOffset(p,point):null;return {selected,html:(selected&&(point[0]!==actual[0]||point[1]!==actual[1])?'<path class="pin-leader" d="M'+actual[0]+','+actual[1]+' L'+point[0]+','+point[1]+'"/>':'')+'<g class="pin '+(selected?'selected':'')+'" transform="translate('+point[0]+','+point[1]+')" role="button" tabindex="0" aria-label="'+esc(p.name)+': Details öffnen'+(selected?', Etappe '+(index+1):'')+'" data-detail="'+p.id+'" opacity="'+(selected?1:available.has(p.id)?.55:.18)+'"><title>'+esc(p.name)+'</title><circle class="hit-target" r="16"/><circle class="visual-marker" r="'+(selected?10:4)+'"/>'+(selected?'<text class="number" y=".5">'+(index+1)+'</text>':'')+(offset?'<text x="'+offset[0]+'" y="'+offset[1]+'" text-anchor="'+offset[2]+'">'+esc(p.name)+'</text>':'')+'</g>'};});$('#mapPins').innerHTML=contents.filter(Boolean).sort((a,b)=>Number(a.selected)-Number(b.selected)).map(item=>item.html).join('');updateMapView();}

async function loadMap(){try{const r=await fetch('japan.geo.json');if(!r.ok)throw Error();geometry=await r.json();const polygons=geometry.type==='MultiPolygon'?geometry.coordinates:[geometry.coordinates];$('#land').innerHTML=polygons.map(poly=>`<path class="land-shape" d="${poly.map(ring=>ring.map(([lon,lat],i)=>{const [x,y]=project(lon,lat);return `${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`}).join(' ')+' Z').join(' ')}"/>`).join('');renderMap();}catch{geometry=null;['zoomIn','zoomOut','mapReset'].forEach(id=>$('#'+id).disabled=true);$('.map-wrap').innerHTML='<div class="empty" style="padding:30px"><h3>Karte nicht geladen.</h3><p>Die Ortsliste und deine Route bleiben nutzbar. Lade die Seite erneut, um es noch einmal zu versuchen.</p></div>';}}
function render(){$('#startDate').value=state.start;$('#endDate').value=state.end;renderPlaces();renderRoute();renderSeason();renderPreferences();window.StayPlanner?.render();}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-detail]');if(!b)return;if(b.dataset.detail){details(b.dataset.detail);return;}if(b.dataset.add){const id=b.dataset.add;addPlace(id);restoreControl('[data-add="'+id+'"]');return;}if(b.dataset.detailAdd){const id=b.dataset.detailAdd;addPlace(id);detailReturn=null;$('#detailDialog').close();restoreControl('[data-add="'+id+'"]');return;}if(b.dataset.remove){const index=state.stops.findIndex(s=>s.id===b.dataset.remove);commit(()=>state.stops=state.stops.filter(s=>s.id!==b.dataset.remove));const next=state.stops[Math.min(index,state.stops.length-1)];if(next)restoreControl('[data-stop="'+next.id+'"] .place-link');else $('#demoBtn').focus({preventScroll:true});toast('Ort entfernt. Du kannst die Änderung rückgängig machen.');return;}if(b.dataset.night){const id=b.dataset.night,d=Number(b.dataset.delta);commit(()=>{state.stops.find(s=>s.id===id).nights+=d;});restoreControl('[data-night="'+id+'"][data-delta="'+d+'"]');return;}if(b.dataset.move){moveStop(b.dataset.move,Number(b.dataset.delta));return;}if(b.dataset.planningStage){switchPlanningStage(b.dataset.planningStage);return;}if(b.dataset.filter){filter=b.dataset.filter;$('#mobilePlaceFilter').value=filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter===filter));renderPlaces();renderMap();return;}if(b.dataset.view){$('.workspace').dataset.view=b.dataset.view;requestAnimationFrame(()=>$('.mobile-tabs').scrollIntoView({block:'start'}));document.querySelectorAll('[data-view].mobile-tabs button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.mobile-tabs button').forEach(x=>x.classList.toggle('active',x===b));return;}if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.id==='resetSearch'){search='';$('#search').value='';filter='all';document.querySelector('[data-filter="all"]').click();}if(b.id==='overviewExport')exportPlan();if(b.id==='overviewPrint')printPlan();});
function restoreControl(selector){const target=document.querySelector(selector);if(target&&!target.disabled&&target.getClientRects().length)target.focus({preventScroll:true});else{const fallback=document.querySelector('.stop .place-link');if(fallback?.getClientRects().length)fallback.focus({preventScroll:true});else document.querySelector('.mobile-tabs button.active')?.focus({preventScroll:true});}}
$('#dateForm').addEventListener('submit',e=>{e.preventDefault();const start=$('#startDate').value,end=$('#endDate').value;if(!validDate(start)||!validDate(end)||dateValue(end)<=dateValue(start)){const error=$('#dateError');error.hidden=false;error.textContent='Die Abreise muss nach der Ankunft liegen. Deine Route bleibt erhalten.';return;}if((dateValue(end)-dateValue(start))/86400000>120){$('#dateError').hidden=false;$('#dateError').textContent='Für diesen Prototyp bitte höchstens 120 Nächte wählen.';return;}$('#dateError').hidden=true;commit(()=>{state.start=start;state.end=end;});toast('Zeitraum aktualisiert. Nächte und Reihenfolge bleiben erhalten.');});
$('#search').addEventListener('input',e=>{search=e.target.value.trim().toLocaleLowerCase('de');renderPlaces();renderMap();});
$('#undoBtn').addEventListener('click',()=>{if(!history.length)return;cancelRouteDrag();editGeneration++;state=JSON.parse(history.pop());save();render();toast('Letzte Änderung rückgängig gemacht');});
$('#clearBtn').addEventListener('click',()=>{commit(()=>{state.stops=[];state.dayItems=[];state.accommodations=[];});toast('Route geleert · Rückgängig ist verfügbar');});
$('#demoBtn').addEventListener('click',()=>{commit(()=>{state.stops=demoRoute();state.dayItems=[];state.accommodations=[];});toast('Beispielroute geladen · Nächte bei Bedarf anpassen');});
$('#mapReset').addEventListener('click',()=>{filter='all';search='';$('#search').value='';document.querySelector('[data-filter="all"]').click();mapZoom=1;mapCenter=[360,330];updateMapView();toast('Ganz Japan wird angezeigt');});
$('#seasonBtn').addEventListener('click',seasonDetails);$('#overviewBtn').addEventListener('click',overview);$('#exportBtn').addEventListener('click',exportPlan);
$('#japanMap').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.detail){e.preventDefault();details(e.target.dataset.detail);}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#detailDialog').addEventListener('close',()=>{if(detailReturn){const p=detailReturn;detailReturn=null;const selector=p.map?'#mapPins [data-detail="'+p.id+'"]':'.place-body[data-detail="'+p.id+'"]';restoreControl(selector);}});
function updateMapView(){const svg=$('#japanMap');if(!svg)return;const w=720/mapZoom,h=660/mapZoom;svg.setAttribute('viewBox',[mapCenter[0]-w/2,mapCenter[1]-h/2,w,h].join(' '));const scale=Math.min(svg.clientWidth/w,svg.clientHeight/h);if(scale>0){svg.querySelectorAll('.hit-target').forEach(el=>el.setAttribute('r',22/scale));svg.querySelectorAll('.visual-marker').forEach(el=>el.setAttribute('r',(el.closest('.selected')?10:4)/scale));svg.querySelectorAll('.pin text:not(.number)').forEach(el=>{el.style.fontSize=(12/scale)+'px';el.dataset.baseX??=el.getAttribute('x');el.dataset.baseY??=el.getAttribute('y');el.setAttribute('x',Number(el.dataset.baseX)/scale);el.setAttribute('y',Number(el.dataset.baseY)/scale);});svg.querySelectorAll('.number').forEach(el=>el.style.fontSize=(10/scale)+'px');}$('#zoomOut').disabled=mapZoom<=1;$('#zoomIn').disabled=mapZoom>=4;}
$('#zoomIn').addEventListener('click',()=>{if(mapZoom===1)mapCenter=[420,440];mapZoom=Math.min(4,mapZoom+1);renderMap();});
$('#zoomOut').addEventListener('click',()=>{mapZoom=Math.max(1,mapZoom-1);if(mapZoom===1)mapCenter=[360,330];renderMap();});
$('#japanMap').addEventListener('keydown',e=>{if(e.target!==$('#japanMap'))return;const moves={ArrowLeft:[-30,0],ArrowRight:[30,0],ArrowUp:[0,-30],ArrowDown:[0,30]};if(moves[e.key]){e.preventDefault();mapCenter=mapCenter.map((v,i)=>v+moves[e.key][i]/mapZoom);updateMapView();}});
$('#japanMap').addEventListener('pointerdown',e=>{if(e.target.closest('.pin'))return;pan={x:e.clientX,y:e.clientY,center:[...mapCenter]};e.currentTarget.setPointerCapture(e.pointerId);});
$('#japanMap').addEventListener('pointermove',e=>{if(!pan)return;const svg=e.currentTarget,scale=Math.min(svg.clientWidth/(720/mapZoom),svg.clientHeight/(660/mapZoom));if(!Number.isFinite(scale)||scale<=0){pan=null;return;}mapCenter=[pan.center[0]-(e.clientX-pan.x)/scale,pan.center[1]-(e.clientY-pan.y)/scale];updateMapView();});
$('#japanMap').addEventListener('pointerup',()=>pan=null);$('#japanMap').addEventListener('pointercancel',()=>pan=null);
window.addEventListener('resize',scheduleMapRender);document.querySelectorAll('.mobile-tabs button').forEach(b=>b.addEventListener('click',scheduleMapRender));
if(typeof ResizeObserver==='function'){const mapResizeObserver=new ResizeObserver(scheduleMapRender);mapResizeObserver.observe($('#japanMap'));}

let routeDrag=null;
function moveStop(id,delta){const index=state.stops.findIndex(s=>s.id===id),target=index+delta;if(index<0||target<0||target>=state.stops.length)return;commit(()=>{const [stop]=state.stops.splice(index,1);state.stops.splice(target,0,stop);});restoreControl('[data-drag="'+id+'"]');toast(place(id).name+' ist jetzt Etappe '+(target+1));}
function cancelRouteDrag(){if(!routeDrag)return;const drag=routeDrag;routeDrag=null;cancelAnimationFrame(drag.frame);drag.ghost?.remove();drag.article?.classList.remove('dragging');document.querySelectorAll('.drop-before,.drop-after').forEach(el=>el.classList.remove('drop-before','drop-after'));document.body.classList.remove('route-dragging');try{drag.handle.releasePointerCapture(drag.pointerId);}catch{}if(drag.active)restoreControl('[data-drag="'+drag.id+'"]');}
function markDrop(){if(!routeDrag?.active)return;const drag=routeDrag;document.querySelectorAll('.drop-before,.drop-after').forEach(el=>el.classList.remove('drop-before','drop-after'));const others=[...document.querySelectorAll('.stop')].filter(el=>el!==drag.article);let index=others.findIndex(el=>{const rect=el.getBoundingClientRect();return drag.y<rect.top+rect.height/2;});if(index<0)index=others.length;drag.target=index;if(index<others.length)others[index].classList.add('drop-before');else others.at(-1)?.classList.add('drop-after');drag.ghost.style.transform='translate('+drag.x+'px,'+drag.y+'px)';}
function routeAutoScroll(){if(!routeDrag?.active)return;const pane=$('.route-pane'),rect=pane.getBoundingClientRect();const scrollable=pane.scrollHeight>pane.clientHeight+1&&getComputedStyle(pane).overflowY==='auto';const top=scrollable?Math.max(0,rect.top):0,bottom=scrollable?Math.min(innerHeight,rect.bottom):innerHeight;const speed=routeDrag.y<top+65?-12:routeDrag.y>bottom-65?12:0;if(speed){if(scrollable)pane.scrollTop+=speed;else window.scrollBy(0,speed);markDrop();}routeDrag.frame=requestAnimationFrame(routeAutoScroll);}
$('#routeList').addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-drag]');if(!handle||e.button!==0||state.stops.length<2)return;cancelRouteDrag();routeDrag={id:handle.dataset.drag,pointerId:e.pointerId,handle,article:handle.closest('.stop'),startX:e.clientX,startY:e.clientY,x:e.clientX,y:e.clientY,active:false,target:state.stops.findIndex(s=>s.id===handle.dataset.drag)};handle.focus({preventScroll:true});handle.setPointerCapture(e.pointerId);});
$('#routeList').addEventListener('pointermove',e=>{if(!routeDrag||e.pointerId!==routeDrag.pointerId)return;const drag=routeDrag;drag.x=e.clientX;drag.y=e.clientY;if(!drag.active&&Math.hypot(drag.x-drag.startX,drag.y-drag.startY)>6){drag.active=true;drag.article.classList.add('dragging');document.body.classList.add('route-dragging');drag.ghost=document.createElement('div');drag.ghost.className='route-drag-ghost';drag.ghost.setAttribute('aria-hidden','true');drag.ghost.textContent=place(drag.id).name;document.body.appendChild(drag.ghost);routeAutoScroll();}if(drag.active){e.preventDefault();markDrop();}});
$('#routeList').addEventListener('pointerup',e=>{if(!routeDrag||e.pointerId!==routeDrag.pointerId)return;const {id,target,active,x,y}=routeDrag,oldIndex=state.stops.findIndex(s=>s.id===id),rect=$('.route-pane').getBoundingClientRect();const inside=x>=rect.left-25&&x<=rect.right+25&&y>=rect.top-25&&y<=rect.bottom+25;cancelRouteDrag();if(active&&inside&&target!==oldIndex){commit(()=>{const [stop]=state.stops.splice(oldIndex,1);state.stops.splice(target,0,stop);});restoreControl('[data-drag="'+id+'"]');toast(place(id).name+' ist jetzt Etappe '+(target+1));}else if(active&&!inside)toast('Verschieben abgebrochen. Die Route bleibt erhalten.');});
$('#routeList').addEventListener('pointercancel',cancelRouteDrag);
$('#routeList').addEventListener('lostpointercapture',cancelRouteDrag);
$('#routeList').addEventListener('keydown',e=>{const h=e.target.closest('[data-drag]');if(h&&['ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();const index=state.stops.findIndex(s=>s.id===h.dataset.drag);moveStop(h.dataset.drag,e.key==='Home'?-index:e.key==='End'?state.stops.length-index-1:e.key==='ArrowUp'?-1:1);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&routeDrag){e.preventDefault();cancelRouteDrag();toast('Verschieben abgebrochen');}});
window.addEventListener('blur',cancelRouteDrag);
function dayPlanForm(p){const stay=itinerary().find(r=>r.id===p.id),date=stay?.arrival||state.start;return '<form class="day-plan-form" id="dayPlanForm" data-destination="'+p.id+'"><h3>Ein Erlebnis im Tagesplan</h3><p>Aktivität auswählen oder einen Tagesausflug ergänzen. Verbraucht keine zusätzliche Nacht.</p><label>Datum<input id="dayPlanDate" type="date" value="'+date+'" min="'+state.start+'" max="'+state.end+'" required></label><label>Übernachtungsbasis<select id="dayPlanBase"><option value="">Noch offen</option>'+itinerary().map(r=>'<option value="'+r.id+'" '+(r.id===(stay?.id||itinerary()[0]?.id)?'selected':'')+'>'+esc(r.p.name)+'</option>').join('')+'</select></label><label>Erlebnis<input id="dayPlanTitle" maxlength="250" value="Tagesausflug nach '+esc(p.name)+'" required></label><label>Tageszeit<select id="dayPlanSlot"><option value="flexible">Ohne feste Tageszeit</option><option value="morning">Vormittag</option><option value="afternoon">Nachmittag</option><option value="evening">Abend</option></select></label><input id="dayPlanType" type="hidden" value="daytrip"><label>Notiz (optional)<input id="dayPlanNote" maxlength="500" placeholder="Zum Beispiel: früh starten, Nachmittag frei lassen"></label><p id="dayPlanError" class="error" role="alert" hidden></p><button class="button dark" type="submit">Zum Tagesplan hinzufügen</button></form>';}
function dayItemWarnings(item){const warnings=[];if(item.date<state.start||item.date>state.end)warnings.push('Datum außerhalb der Reise');if(item.baseId){const basis=itinerary().find(r=>r.id===item.baseId);if(!basis)warnings.push('Übernachtungsbasis entfernt');else if(item.date<basis.arrival||item.date>=basis.departure)warnings.push('Übernachtungsbasis an diesem Tag prüfen');}return warnings;}
function sortedDayItems(){return [...state.dayItems].sort((a,b)=>a.date.localeCompare(b.date)||['morning','afternoon','evening','flexible'].indexOf(a.slot||'flexible')-['morning','afternoon','evening','flexible'].indexOf(b.slot||'flexible'));}
function renderDayItems(){const list=$('#dayItemsList');if(!list)return;list.innerHTML=sortedDayItems().map(item=>'<article class="day-item"><div><span class="day-item-date">'+dateLabel(item.date)+' · '+(window.StayPlanner?.slots[item.slot||'flexible']||'Ohne feste Tageszeit')+' · '+(item.type==='free'?'Freie Zeit':item.type==='daytrip'?'Tagesausflug':'Aktivität')+'</span><strong>'+esc(item.title)+'</strong><span>'+esc(place(item.destinationId).name)+(item.baseId?' · Basis: '+esc(place(item.baseId)?.name||'offen'):' · Basis offen')+'</span>'+(window.ActivityInfo?.html(item.destinationId,item.title,{compact:true})||'')+(item.note?'<p>'+esc(item.note)+'</p>':'')+dayItemWarnings(item).map(w=>'<p class="day-warning">'+esc(w)+'</p>').join('')+'</div><div class="day-item-actions"><button class="text-button" data-edit-day="'+esc(item.uid)+'">Ändern</button><button class="remove-control" data-remove-day="'+esc(item.uid)+'" aria-label="'+esc(item.title)+' entfernen">'+icon('close')+'</button></div></article>').join('')||'<p class="day-empty">Öffne die Details eines Ortes, um einen Tagesausflug oder eine Aktivität einzuplanen.</p>';$('[data-day-count]').textContent=state.dayItems.length+' Erlebnisse';}
function accommodationSummary(){return (state.accommodations||[]).length?'<h3 class="day-plan-heading">Deine Unterkünfte</h3>'+state.accommodations.map(a=>{const h=window.StayPlanner.selectedHotel(state,a.destinationId);return '<article class="overview-hotel"><strong>'+esc(place(a.destinationId)?.name||a.destinationId)+' · '+esc(h?.name||'Auswahl nicht mehr im Katalog')+'</strong><p>Ausgewählt, nicht gebucht'+(!state.stops.some(s=>s.id===a.destinationId)?' · Ort nicht mehr in der Route':'')+'</p>'+(h?'<a href="'+esc(h.url)+'" target="_blank" rel="noopener">Betreiberquelle ↗</a>':'')+'</article>';}).join(''):'';}
function dayItemsTable(){if(!state.dayItems.length)return '';return '<h3 class="day-plan-heading">Dein Tagesplan</h3><table class="overview-table day-overview"><thead><tr><th>Datum</th><th>Erlebnis</th><th>Basis / Hinweise</th></tr></thead><tbody>'+sortedDayItems().map(item=>'<tr><td>'+dateLabel(item.date)+'<br>'+esc(window.StayPlanner?.slots[item.slot||'flexible']||'Ohne feste Tageszeit')+'</td><td><strong>'+esc(item.title)+'</strong><span>'+esc(place(item.destinationId).name)+' · '+(item.type==='free'?'Freie Zeit':item.type==='daytrip'?'Tagesausflug':'Aktivität')+'</span>'+(window.ActivityInfo?.html(item.destinationId,item.title,{compact:true})||'')+(item.note?'<span>'+esc(item.note)+'</span>':'')+'</td><td>'+esc(place(item.baseId)?.name||'Offen')+dayItemWarnings(item).map(w=>'<span>'+esc(w)+'</span>').join('')+'</td></tr>').join('')+'</tbody></table>';}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.planActivity){const p=place(button.dataset.planActivity),activity=p.activities[Number(button.dataset.activityIndex)];$('#dayPlanTitle').value=typeof activity==='string'?activity:activity.title;$('#dayPlanType').value='activity';$('#dayPlanDate').focus();$('#dayPlanForm').scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}if(button.dataset.removeDay){commit(()=>state.dayItems=state.dayItems.filter(item=>item.uid!==button.dataset.removeDay));toast('Erlebnis entfernt · Rückgängig ist verfügbar');}if(button.dataset.editDay){const item=state.dayItems.find(item=>item.uid===button.dataset.editDay);if(!item)return;details(item.destinationId);$('#dayPlanForm').dataset.editUid=item.uid;$('#dayPlanDate').value=item.date;$('#dayPlanBase').value=item.baseId||'';$('#dayPlanTitle').value=item.title;$('#dayPlanType').value=item.type;$('#dayPlanSlot').value=item.slot||'flexible';$('#dayPlanNote').value=item.note||'';$('#dayPlanForm button[type=submit]').textContent='Änderung speichern';$('#dayPlanDate').focus();}});
document.addEventListener('submit',e=>{if(e.target.id!=='dayPlanForm')return;e.preventDefault();const form=e.target,date=$('#dayPlanDate').value,title=$('#dayPlanTitle').value.trim();if(!validDate(date)||date<state.start||date>state.end||!title){$('#dayPlanError').hidden=false;$('#dayPlanError').textContent='Wähle ein Datum innerhalb der Reise und ein Erlebnis.';return;}const item={uid:form.dataset.editUid||crypto.randomUUID(),type:$('#dayPlanType').value,destinationId:form.dataset.destination,date,baseId:$('#dayPlanBase').value||null,title,slot:$('#dayPlanSlot').value,note:$('#dayPlanNote').value.trim()};commit(()=>{const index=state.dayItems.findIndex(existing=>existing.uid===item.uid);if(index>=0)state.dayItems[index]=item;else state.dayItems.push(item);});$('#detailDialog').close();toast('Erlebnis im Tagesplan gespeichert · ohne zusätzliche Nacht');});



function routingPanel(from,to){return '<details class="routing-panel"><summary>Datumsgenauen Fahrplan prüfen</summary><form class="routing-form" data-routing-from="'+from.id+'" data-routing-to="'+to.id+'" data-routing-date="'+from.departure+'"><p>'+dateLabel(from.departure,true)+' · '+esc(from.p.name)+' nach '+esc(to.p.name)+'</p><label>Abfahrt ab (Japanzeit)<input type="time" value="09:00" required></label><button class="button outline" type="submit">Fahrplan prüfen</button><div class="routing-result" role="status" aria-live="polite"></div></form></details>';}
function routeTimestamp(value){return typeof value==='string'&&value.length>=16?dateLabel(value.slice(0,10))+' '+value.slice(11,16)+' JST':'Zeit offen';}
function liveRoutingHtml(data){const statuses={provider_not_configured:'Datumsgenaue Suche benötigt einen Anbieterzugang. Nutze die ungefähre Option oder den externen Planer.',no_connection:'Keine Verbindung im unterstützten Suchumfang gefunden. Lokale Busse, Fernbusse, Fähren und Flüge werden hier nicht abgedeckt. Prüfe weitere Verkehrsmittel beim Betreiber.',timeout:'Die Fahrplansuche hat zu lange gedauert. Versuche es erneut oder nutze den externen Planer.',provider_error:'Die Fahrplanquelle ist gerade nicht erreichbar. Versuche es erneut oder nutze den externen Planer.',unknown_shape:'Die Antwort der Fahrplanquelle konnte nicht zuverlässig gelesen werden. Nutze den externen Planer.',invalid_date:'Das Reisedatum konnte nicht geprüft werden. Passe den Zeitraum an.',invalid_time:'Bitte eine gültige Uhrzeit auswählen.',invalid_destination:'Für diese Ortskombination ist die Anfrage nicht verfügbar.'};if(data?.status!=='ok')return '<p>'+esc(statuses[data?.status]||'Fahrplan derzeit nicht verfügbar. Nutze die ungefähre Option oder den externen Planer.')+'</p>';const modes={walk:'Zu Fuß',superexpress_train:'Shinkansen',sleeper_ultraexpress:'Nachtzug',ultraexpress_train:'Expresszug',express_train:'Expresszug',rapid_train:'Schnellzug',semiexpress_train:'Regionalzug',local_train:'Regionalzug',shuttle_bus:'Shuttlebus'};return '<p>Ergebnis dieser Anfrage · '+esc(data.notice||'Keine Buchungsbestätigung. Nicht gespeichert oder exportiert.')+'</p>'+(data.routes||[]).slice(0,3).map((route,i)=>'<article class="live-route"><strong>Option '+(i+1)+' · '+duration(route.totalMinutes)+'</strong><p>'+esc(routeTimestamp(route.departure))+' – '+esc(routeTimestamp(route.arrival))+'</p><p>'+duration(route.movingMinutes)+' Bewegung · '+duration(route.waitMinutes)+' bekannte Umstiegs-/Wartezeit'+(route.initialWaitMinutes>0?' · '+duration(route.initialWaitMinutes)+' anfängliche Wartezeit':'')+'</p><ol>'+route.segments.map(segment=>'<li><strong>'+esc(segment.from)+' – '+esc(segment.to)+'</strong><span>'+esc(modes[segment.mode]||segment.mode)+(segment.line?' · '+esc(segment.line):'')+'</span><span>'+esc(routeTimestamp(segment.departure))+' – '+esc(routeTimestamp(segment.arrival))+'</span><span>'+duration(segment.durationMinutes)+' · '+(segment.timetable?'Fahrplanbezug':'Anbieterschätzung')+'</span></li>').join('')+'</ol><p>'+esc(route.bufferNotice||'Hotelwege und zusätzliche Komfortpuffer sind nicht eingerechnet.')+'</p><p>Fahrpreise, Buchbarkeit und Hotelwege offen. Diese Antwort wird weder gespeichert noch ins PDF übernommen.</p><a href="'+esc(route.source)+'" target="_blank" rel="noopener">Anbieterinformationen ↗</a></article>').join('');}
document.addEventListener('input',e=>{const form=e.target.closest('.routing-form');if(!form)return;form.dataset.requestToken=String(Number(form.dataset.requestToken||0)+1);form.querySelector('button').disabled=false;form.querySelector('.routing-result').innerHTML='';});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('.routing-form'))return;e.preventDefault();const time=form.querySelector('input').value,target=form.querySelector('.routing-result'),button=form.querySelector('button'),generation=routingGeneration,token=String(Number(form.dataset.requestToken||0)+1);form.dataset.requestToken=token;if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)){target.textContent='Bitte eine gültige Uhrzeit auswählen.';return;}button.disabled=true;target.textContent='Datumsgenauer Fahrplan wird geprüft …';try{const data=window.TripServices?.routing?await window.TripServices.routing(form.dataset.routingFrom,form.dataset.routingTo,form.dataset.routingDate,time):{status:'provider_not_configured'};if(!form.isConnected||generation!==routingGeneration||form.dataset.requestToken!==token)return;target.innerHTML=liveRoutingHtml(data);}catch{if(form.isConnected&&generation===routingGeneration&&form.dataset.requestToken===token)target.textContent='Fahrplansuche nicht erreichbar. Prüfe die Verbindung über den externen Planer.';}finally{if(form.isConnected&&form.dataset.requestToken===token)button.disabled=false;}});

function qualityWarnings(){const pace=state.pace||'relaxed',factor={relaxed:1,balanced:.75,active:.5}[pace],limit={relaxed:240,balanced:300,active:360}[pace],rows=itinerary(),warnings=[];for(const [i,r] of rows.entries()){const recommended=Math.max(1,Math.ceil(r.p.nights*factor));if(r.nights<recommended)warnings.push(r.p.name+': '+r.nights+' Nächte liegen unter dem redaktionellen Ausgangspunkt für dieses Tempo ('+recommended+' Nächte). Plane mehr Zeit oder weniger Aktivitäten.');if(i<rows.length-1){const t=transfer(r.p,rows[i+1].p,r.departure);if(t.min!==null&&t.min>limit)warnings.push(r.p.name+' nach '+rows[i+1].p.name+': '+duration(t.min)+' reine Fahrzeit, zuzüglich Wartezeiten. Halte den restlichen Reisetag frei oder ergänze eine Zwischenetappe.');}}if(rows.length&&state.arrivalPlaceId&&state.arrivalPlaceId!==rows[0].id)warnings.push('Ankunft in '+place(state.arrivalPlaceId).name+', erste Übernachtungsbasis '+rows[0].p.name+': Anschluss separat prüfen.');if(rows.length&&state.departurePlaceId&&state.departurePlaceId!==rows.at(-1).id)warnings.push('Letzte Übernachtungsbasis '+rows.at(-1).p.name+', Abreise aus '+place(state.departurePlaceId).name+': Anschluss separat prüfen.');return warnings;}
function renderQualityHints(){const warnings=qualityWarnings(),section=$('#qualityHints');if(!section)return;section.hidden=!warnings.length;$('#qualityHintsList').innerHTML=warnings.map(w=>'<li>'+esc(w)+'</li>').join('');}
function renderPreferences(){const pace=$('#pacePreference');if(!pace)return;pace.value=state.pace||'relaxed';$('#budgetPreference').value=state.budget??'';const options='<option value="">Noch offen</option>'+[...PLACES].sort((a,b)=>a.name.localeCompare(b.name,'de')).map(p=>'<option value="'+p.id+'">'+esc(p.name)+' · '+esc(p.region)+'</option>').join('');$('#arrivalPlacePreference').innerHTML=options;$('#departurePlacePreference').innerHTML=options;$('#arrivalPlacePreference').value=state.arrivalPlaceId||'';$('#departurePlacePreference').value=state.departurePlaceId||'';document.querySelectorAll('[name=interest]').forEach(input=>input.checked=state.interests?.includes(input.value)||false);}
$('#preferencesForm').addEventListener('submit',e=>{e.preventDefault();const pace=$('#pacePreference').value,interests=[...document.querySelectorAll('[name=interest]:checked')].map(input=>input.value),raw=$('#budgetPreference').value,budget=raw===''?null:Number(raw);if(budget!==null&&(!Number.isFinite(budget)||budget<0||budget>10000000))return;commit(()=>{state.pace=pace;state.interests=interests;state.budget=budget;state.arrivalPlaceId=$('#arrivalPlacePreference').value||null;state.departurePlaceId=$('#departurePlacePreference').value||null;});toast('Reisevorlieben übernommen. Deine Route bleibt erhalten.');});
try{$('#reduceMotion').checked=localStorage.getItem('tabi-reduce-motion')==='true';}catch{}document.documentElement.dataset.reduceMotion=String($('#reduceMotion').checked);
$('#reduceMotion').addEventListener('change',e=>{document.documentElement.dataset.reduceMotion=String(e.target.checked);try{localStorage.setItem('tabi-reduce-motion',String(e.target.checked));}catch{}});

render();loadMap();

let recoveryDraft=null,cloudRevision=null,cloudStatus='loading',pdfBusy=false;
function applySavedState(saved){if(!saved||!validDate(saved.start)||!validDate(saved.end)||dateValue(saved.end)<=dateValue(saved.start)||!Array.isArray(saved.stops)||!saved.stops.every(stop=>place(stop.id)&&Number.isInteger(stop.nights)&&stop.nights>0&&stop.nights<=30)||new Set(saved.stops.map(stop=>stop.id)).size!==saved.stops.length)return false;cancelRouteDrag();state={...saved,dayItems:Array.isArray(saved.dayItems)?saved.dayItems.filter(validDayItem):[],accommodations:Array.isArray(saved.accommodations)?saved.accommodations:[]};history=[];render();return true;}
function handleCloudLoad(result){if(!result)return;if(!result.error&&editGeneration===0&&result.state)applySavedState(result.state);recoveryDraft=result.draft;try{if(!recoveryDraft){const legacy=JSON.parse(localStorage.getItem(STORAGE_KEY));if(legacy&&validDate(legacy.start)&&validDate(legacy.end)&&dateValue(legacy.end)>dateValue(legacy.start)&&Array.isArray(legacy.stops)&&legacy.stops.every(stop=>place(stop.id)&&Number.isInteger(stop.nights)&&stop.nights>0&&stop.nights<=30))recoveryDraft={...legacy,dayItems:Array.isArray(legacy.dayItems)?legacy.dayItems.filter(validDayItem):[],accommodations:Array.isArray(legacy.accommodations)?legacy.accommodations:[]};}}catch{}$('#recoverDraftBtn').hidden=!recoveryDraft;}
if(window.TripServices){window.TripServices.subscribe(info=>{cloudStatus=info.status;if(info.revision!==undefined)cloudRevision=info.revision;const labels={loading:'Gespeicherte Reise wird geladen …',ready:'Privater Reiseplan geladen',pending:'Änderungen warten auf Speicherung …',saving:'Reiseplan wird gespeichert …',saved:'Reiseplan privat gespeichert',conflict:'Anderer gespeicherter Stand vorhanden. Dein Entwurf bleibt erhalten.',offline:'Cloud-Speicherung nicht erreichbar. Dein Entwurf bleibt auf diesem Gerät.',sign_in_required:'Anmeldung erforderlich. Dein Entwurf bleibt auf diesem Gerät.'};$('#saveStatus').textContent=labels[info.status]||'Speicherstatus offen';if(info.recoveryAvailable===false&&['pending','saving','offline','sign_in_required','conflict'].includes(info.status))$('#saveStatus').textContent=({pending:'Änderungen warten auf Cloud-Speicherung.',saving:'Cloud-Speicherung läuft.',offline:'Cloud-Speicherung nicht erreichbar.',sign_in_required:'Anmeldung erforderlich.',conflict:'Anderer gespeicherter Stand vorhanden.'}[info.status])+' Entwurf nur in dieser Sitzung; lokale Sicherung nicht möglich. Über PDF herunterladen sichern.';$('#retrySaveBtn').hidden=!['offline','sign_in_required'].includes(info.status);$('#reloadCloudBtn').hidden=info.status!=='conflict';if(info.draft)recoveryDraft=info.draft;});window.TripServices.load().then(handleCloudLoad).catch(()=>{});}
$('#retrySaveBtn').addEventListener('click',()=>Promise.resolve(window.TripServices?.retry()).then(result=>{if(result?.state)handleCloudLoad(result);}));
$('#reloadCloudBtn').addEventListener('click',async()=>{const local=JSON.parse(JSON.stringify(state));const result=await window.TripServices.reload();if(result?.state&&applySavedState(result.state)){editGeneration=0;recoveryDraft=local;$('#recoverDraftBtn').hidden=false;toast('Gespeicherten Stand geladen. Dein vorheriger Entwurf ist wiederherstellbar.');}});
$('#recoverDraftBtn').addEventListener('click',()=>{if(!recoveryDraft)return;const draft=recoveryDraft;if(!window.TripServices.restoreDraft(draft)){toast('Zuerst den gespeicherten Stand laden oder die Verbindung erneut versuchen.');return;}if(applySavedState(draft)){editGeneration++;recoveryDraft=null;$('#recoverDraftBtn').hidden=true;toast('Lokaler Entwurf wiederhergestellt und zum Speichern vorgemerkt.');}});

if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_japan_itinerary',title:'Japan-Reiseplan lesen',description:'Liest den sichtbaren Japan-Planungsentwurf mit Nächten und als Beispiel gekennzeichneten Transfers. Ändert keine Daten.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Ein leeres Eingabeobjekt ist erforderlich.');const rows=itinerary();return{prototype:true,start:state.start,end:state.end,availableNights:tripNights(),plannedNights:assigned(),dayItems:state.dayItems,stops:rows.map((r,i)=>({name:r.p.name,arrival:r.arrival,departure:r.departure,nights:r.nights,transfer:i<rows.length-1?{...transfer(r.p,rows[i+1].p,r.departure),evidence:window.TransferEngine?'official_orientation':'illustrative'}:null}))};}})).catch(()=>{});}catch{}}

$('#mobilePlaceFilter').addEventListener('change',event=>{document.querySelector('[data-filter="'+event.target.value+'"]').click();});

function switchPlanningStage(next){planningStage=next==='stays'?'stays':'route';$('#main').dataset.planningStage=planningStage;$('.workspace').hidden=planningStage==='stays';$('.mobile-tabs').hidden=planningStage==='stays';$('#stayPlanner').hidden=planningStage!=='stays';document.querySelectorAll('[data-planning-stage]').forEach(button=>{const active=button.dataset.planningStage===planningStage;button.classList.toggle('active',active);if(button.closest('.planning-steps')){if(active)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');}});if(planningStage==='stays'){window.StayPlanner.render();$('#stayPlannerHeading').focus({preventScroll:true});}else scheduleMapRender();$('.planning-steps').scrollIntoView({block:'start'});}
window.StayPlanner.init({getState:()=>state,getRows:itinerary,getPlace:place,addDays,dateLabel,commit,details,warnings:dayItemWarnings,toast,canUndo:()=>history.length>0,undo:()=>$('#undoBtn').click(),editLegacy:uid=>document.querySelector('[data-edit-day="'+uid+'"]').click()});
